#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.." && pwd)";cd "$ROOT";export JAVA_HOME="${JAVA_HOME:-${JAVA_HOME_17_X64:-}}";: "${ZUNGUN_PILOT_TOKEN:?required}"
OUT="${ORDER083_FIELD_RECOVERY_EVIDENCE:-$ROOT/evidence/order083/field-recovery}";mkdir -p "$OUT";GRADLE=(android/gradle/bootstrap-gradle.sh -p android --no-daemon --stacktrace);"${GRADLE[@]}" :app:assembleDebug :app:assembleDebugAndroidTest
adb install -r android/app/build/outputs/apk/debug/app-debug.apk >/dev/null;adb install -r android/app/build/outputs/apk/androidTest/debug/app-debug-androidTest.apk >/dev/null;RUNNER='com.zungun.app.test/androidx.test.runner.AndroidJUnitRunner'
run(){ adb shell am instrument -w -r -e class "com.zungun.app.Order083FieldRecoveryInstrumentedTest#$1" "$RUNNER" | tee "$OUT/$1.log";grep -q 'OK (1 test)' "$OUT/$1.log"; }
off(){ adb shell cmd connectivity airplane-mode enable >/dev/null 2>&1 || { adb shell settings put global airplane_mode_on 1;adb shell am broadcast -a android.intent.action.AIRPLANE_MODE --ez state true >/dev/null 2>&1||true;};sleep 2; }
probe_online(){ timeout 3s adb shell ping -c 1 1.1.1.1 >/dev/null 2>&1; }
on(){ adb shell cmd connectivity airplane-mode disable >/dev/null 2>&1 || { adb shell settings put global airplane_mode_on 0;adb shell am broadcast -a android.intent.action.AIRPLANE_MODE --ez state false >/dev/null 2>&1||true;};local recovered=0;for _ in $(seq 1 20);do if probe_online;then recovered=1;break;fi;sleep 1;done;[[ "$recovered" == 1 ]] || { echo 'CONNECTIVITY_RECOVERY_TIMEOUT' >&2;return 1; };probe_online || { echo 'CONNECTIVITY_POST_LOOP_ASSERTION_FAILED' >&2;return 1; }; }
run phase1SetupOnline;off;run phase2QueueOffline;adb shell am force-stop com.zungun.app;on;adb shell monkey -p com.zungun.app -c android.intent.category.LAUNCHER 1 >/dev/null;sleep 2;run phase3VerifyRecovered
run phase4SetupAmbiguousOnline;off;run phase5QueueAmbiguousOffline;OP="$(adb shell run-as com.zungun.app cat files/order083-ambiguous-operation-id.txt | tr -d '\r\n')";test -n "$OP";node tools/order083/set-pilot-fault.mjs "$OP" | tee "$OUT/fault.json";adb shell am force-stop com.zungun.app;on;adb shell monkey -p com.zungun.app -c android.intent.category.LAUNCHER 1 >/dev/null;sleep 2;run phase6VerifyUnknownThenReconciled
printf '{"ok":true,"fieldOfflineForceStopRecovery":true,"ambiguousUnknownObserved":true,"reconcileBeforeRetry":true,"duplicateEffect":0}\n' > "$OUT/result.json"
